import { List } from '@advui/core'
import { FileIcon, FolderIcon, ImageIcon } from '@advui/icons'

export default function ListBasic() {
  return (
    <List width="100%" maxWidth="$96">
      <List.Item leading={<FolderIcon />} title="Field reports" description="12 files" />
      <List.Item leading={<FileIcon />} title="Budget 2026.xlsx" description="Edited yesterday" />
      <List.Item
        leading={<ImageIcon />}
        title="Site photo.jpg"
        description="2.4 MB"
        trailing="JPG"
      />
    </List>
  )
}

import { List, toast } from '@advui/core'
import { BellIcon, ChevronRightIcon, LockIcon, UserIcon } from '@advui/icons'

const settings = [
  { title: 'Account', description: 'Name, email and photo', icon: <UserIcon /> },
  { title: 'Notifications', description: 'Email and push alerts', icon: <BellIcon /> },
  { title: 'Privacy', description: 'Who can see your activity', icon: <LockIcon /> },
]

export default function ListInteractive() {
  return (
    <List variant="outline" divided width="100%" maxWidth="$96">
      {settings.map((item) => (
        <List.Item
          key={item.title}
          leading={item.icon}
          title={item.title}
          description={item.description}
          trailing={<ChevronRightIcon />}
          onPress={() => toast(`Opening ${item.title}…`)}
        />
      ))}
      <List.Item
        leading={<LockIcon />}
        title="Security keys"
        description="Available on the Pro plan"
        disabled
        onPress={() => {}}
      />
    </List>
  )
}

import { Avatar, Badge, IconButton, List } from '@advui/core'
import { MailIcon } from '@advui/icons'

const team = [
  { name: 'Aung Kyaw', role: 'Field coordinator', status: 'Online' },
  { name: 'Nwe Ni', role: 'Data officer', status: 'Away' },
  { name: 'Hla Min', role: 'Programme manager', status: 'Online' },
]

export default function ListWithAvatars() {
  return (
    <List divided size="sm" width="100%" maxWidth="$96">
      {team.map((person) => (
        <List.Item
          key={person.name}
          leading={<Avatar size="sm" alt={person.name} />}
          title={person.name}
          description={person.role}
          trailing={
            <>
              <Badge
                size="sm"
                variant={person.status === 'Online' ? 'success' : 'secondary'}
                alignSelf="center"
              >
                {person.status}
              </Badge>
              <IconButton size="sm" icon={<MailIcon />} aria-label={`Email ${person.name}`} />
            </>
          }
        />
      ))}
    </List>
  )
}
